  const ib = wrap(ia + 3);
  const vT = vProf[ia];
  const aff = (vProf[ib] * vProf[ib] - vT * vT) / (2 * 3 * ds);
  const aDes = P.kp * (vT - v) + aff;
  const dragA = P.drag * v * v;
  const vxs = Math.max(t.vx, 3);
  const aR = Math.abs(Math.atan2(t.vy - 1.62 * t.yawRate, vxs));
